-- Sustantix AIP · phase 3 compatibility views (generated by tools/schema from src/sheet-model.ts — do not edit by hand)
-- Each view rebuilds one workbook sheet from the normalized model, so the runtime and integrations keep their shape.
create schema if not exists aip_compat;
grant usage on schema aip_compat to authenticated, service_role;
drop view if exists aip_compat."ai_alerts_and_rul";
create view aip_compat."ai_alerts_and_rul" with (security_invoker = true) as
select t.tenant_id, t.code as row_key, t.source_ordinal,
  (t.code)::varchar(200) as "alert_id",
  (j0.code)::varchar(200) as "asset_id",
  (j1.code)::varchar(200) as "plant_id",
  (j0."tag")::varchar(200) as "asset_tag",
  (t."component")::varchar(200) as "component",
  (t."alert_timestamp")::timestamp without time zone as "alert_timestamp",
  (t."model")::varchar(200) as "model",
  (t."risk_score")::numeric(24,3) as "risk_score",
  (t."rul_days")::integer as "rul_days",
  (t."confidence_pct")::numeric(24,2) as "confidence_pct",
  (t."risk_tier")::varchar(200) as "risk_tier",
  (r0.label)::varchar(200) as "alert_status",
  (t."evidence_summary")::varchar(200) as "evidence_summary",
  (t."data_basis")::varchar(200) as "data_basis"
from aip."alert" t
left join aip."asset" j0 on j0.id = t."asset_id"
left join aip."site" j1 on j1.id = t."site_id"
left join aip."ref_status" r0 on r0.id = t."status_id";
comment on view aip_compat."ai_alerts_and_rul" is 'Workbook sheet "AI Alerts & RUL" rebuilt from aip.alert';
grant select on aip_compat."ai_alerts_and_rul" to authenticated, service_role;
drop view if exists aip_compat."prescriptive_actions";
create view aip_compat."prescriptive_actions" with (security_invoker = true) as
select t.tenant_id, t.code as row_key, t.source_ordinal,
  (t.code)::varchar(200) as "recommendation_id",
  (j0.code)::varchar(200) as "alert_id",
  (j1.code)::varchar(200) as "asset_id",
  (j1."tag")::varchar(200) as "asset_tag",
  (t."risk_score")::numeric(24,3) as "risk_score",
  (t."rul_days")::integer as "rul_days",
  (t."recommended_action")::varchar(1000) as "recommended_action",
  (t."cost_now")::numeric(24,2) as "cost_now",
  (t."cost_if_deferred")::numeric(24,2) as "cost_if_deferred",
  (t."cost_avoided")::numeric(24,2) as "cost_avoided",
  (t."confidence_pct")::numeric(24,2) as "confidence_pct",
  (r0.label)::varchar(200) as "decision_status",
  (t."rationale")::varchar(1000) as "rationale",
  (j2.code)::varchar(200) as "plant_id",
  t.currency
from aip."recommendation" t
left join aip."alert" j0 on j0.id = t."alert_id"
left join aip."asset" j1 on j1.id = t."asset_id"
left join aip."ref_status" r0 on r0.id = t."status_id"
left join aip."site" j2 on j2.id = t."site_id";
comment on view aip_compat."prescriptive_actions" is 'Workbook sheet "Prescriptive Actions" rebuilt from aip.recommendation';
grant select on aip_compat."prescriptive_actions" to authenticated, service_role;
drop view if exists aip_compat."work_orders";
