  (t."created_date")::timestamp without time zone as "created_date",
  (t."sla_due")::timestamp without time zone as "sla_due",
  (t."sla_hours")::integer as "sla_hours",
  (t."actual_resolution_hours")::numeric(24,2) as "actual_resolution_hours",
  (t."sla_result")::varchar(200) as "sla_result",
  (t."source_record")::varchar(200) as "source",
  (t."estimated_cost")::numeric(24,2) as "estimated_cost",
  (j2.code)::varchar(200) as "assigned_technician_id",
  (t."assigned_crew")::varchar(200) as "assigned_crew",
