  (j5.code)::varchar(200) as "module_id",
  (t."data_basis")::varchar(200) as "data_basis",
  t.currency
from aip."work_order" t
left join aip."ref_maintenance_type" r0 on r0.id = t."maintenance_type_id"
left join aip."asset" j0 on j0.id = t."asset_id"
left join aip."site" j1 on j1.id = t."site_id"
left join aip."ref_priority" r1 on r1.id = t."priority_id"
left join aip."ref_status" r2 on r2.id = t."status_id"
left join aip."technician" j2 on j2.id = t."technician_id"
left join aip."alert" j3 on j3.id = t."alert_id"
left join aip."part" j4 on j4.id = t."required_part_id"
left join aip."pv_module" j5 on j5.id = t."pv_module_id";
