  (t."verification_method")::varchar(1000) as "verification_method",
  (t."decision_basis")::varchar(1000) as "decision_basis"
from aip."cbm_assessment" t
left join aip."site" j0 on j0.id = t."site_id"
left join aip."asset" j1 on j1.id = t."asset_id"
left join aip."ref_asset_class" r0 on r0.id = j1."asset_class_id"
