  (t."target_view")::varchar(200) as "target_view",
  (t."source_record_id")::varchar(200) as "source_record_id",
  (t."observed_time")::timestamp without time zone as "observed_time",
  (t."signal_name")::varchar(200) as "signal_name",
  (t."observed_value")::numeric(24,2) as "observed_value",
  (t."baseline_or_peer")::numeric(24,2) as "baseline_or_peer",
