drop view if exists aip_compat."reliability_life_history";
create view aip_compat."reliability_life_history" with (security_invoker = true) as
select t.tenant_id, t.code as row_key, t.source_ordinal,
  (t.code)::varchar(200) as "reliability_record_id",
  (t."asset_code")::varchar(200) as "asset_id",
  (t."asset_tag")::varchar(200) as "asset_tag",
  (j0.code)::varchar(200) as "plant_id",
  (r0.label)::varchar(200) as "asset_class",
  (r1.label)::varchar(200) as "failure_mode",
  (t."commissioned_date")::date as "commissioned_date",
  (t."observation_date")::date as "observation_date",
  (t."operating_hours")::numeric(24,2) as "operating_hours",
  (r2.label)::varchar(200) as "event_type",
  (t."failed_surviving")::varchar(200) as "failed_surviving",
  (t."right_censored")::varchar(200) as "right_censored",
  (t."replacement_reset")::varchar(200) as "replacement_reset",
  (t."evidence_source")::varchar(200) as "evidence_source",
  (t."source_mode")::varchar(200) as "source_mode",
  (t."data_quality_status")::varchar(200) as "data_quality_status",
  (j1.code)::varchar(200) as "group_id",
  (j2.code)::varchar(200) as "module_id",
  (t."observation_basis")::varchar(1000) as "observation_basis",
  (t."calendar_exposure_hours")::integer as "calendar_exposure_hours",
  (j3.code)::varchar(200) as "model_id",
  (t."batch_id")::varchar(200) as "batch_id",
  (t."evidence_reference")::varchar(200) as "evidence_reference",
  (t."failure_criterion")::varchar(200) as "failure_criterion",
  (t."data_basis")::varchar(200) as "data_basis"
from aip."life_observation" t
left join aip."site" j0 on j0.id = t."site_id"
left join aip."ref_asset_class" r0 on r0.id = t."asset_class_id"
left join aip."ref_failure_mode" r1 on r1.id = t."failure_mode_id"
left join aip."ref_event_type" r2 on r2.id = t."event_type_id"
left join aip."pv_module_group" j1 on j1.id = t."module_group_id"
left join aip."pv_module" j2 on j2.id = t."pv_module_id"
left join aip."equipment_model" j3 on j3.id = t."equipment_model_id";
comment on view aip_compat."reliability_life_history" is 'Workbook sheet "Reliability_Life_History" rebuilt from aip.life_observation';
grant select on aip_compat."reliability_life_history" to authenticated, service_role;
